def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    if input_data is None:
        return []
    try:
        data = json.loads(input_data)
    except (json.JSONDecodeError, TypeError):
        return []
    recipients = data if isinstance(data, list) else data.get('recipients', [])
    names = [r.get('name', '') for r in recipients if 'name' in r and 'email' in r]
    if not names:
        return []
    email_body = 'Subject: Extracted Names\n\n' + '\n'.join(names)
    if smtp is None:
        server = smtplib.SMTP(smtp_server, smtp_port)
        server.starttls()
        server.login(email_address, email_password)
    else:
        server = smtp
    for r in recipients:
        if 'email' in r:
            server.sendmail(email_address, r['email'], email_body)
    if smtp is None:
        server.quit()
    return names

def task_func(input_data=None, smtp_server=SMTP_SERVER, smtp_port=SMTP_PORT, email_address=EMAIL_ADDRESS, email_password=EMAIL_PASSWORD, smtp=None):
    if input_data is None:
        return []
    try:
        recipients = json.loads(input_data)
    except json.JSONDecodeError:
        return []
    names = []
    emails = []
    for item in recipients:
        name = item.get('name', '')
        email = item.get('email', '')
        if name:
            names.append(name)
        if email:
            emails.append(email)
    if not names:
        return []
    message = f'Subject: Extracted Names\n\n' + '\n'.join(names)
    if smtp is not None:
        smtp.sendmail(email_address, emails, message)
    else:
        server = smtplib.SMTP(smtp_server, smtp_port)
        server.starttls()
        server.login(email_address, email_password)
        server.sendmail(email_address, emails, message)
        server.quit()
    return names

