import json
import re
from collections import Counter

REPLACE_NONE = "None"

def task_func(json_str):
    data = json.loads(json_str)

    def clean(obj):
        if isinstance(obj, dict):
            return {k: clean(v) for k, v in obj.items() if v is not None}
        elif isinstance(obj, list):
            return [clean(item) for item in obj if item is not None]
        elif isinstance(obj, str):
            if re.match(r'^[\w\.-]+@[\w\.-]+\.\w+$', obj):
                return REPLACE_NONE
            return obj
        else:
            return obj

    cleaned_data = clean(data)

    def flatten(obj):
        items = []
        if isinstance(obj, dict):
            for v in obj.values():
                items.extend(flatten(v))
        elif isinstance(obj, list):
            for item in obj:
                items.extend(flatten(item))
        else:
            items.append(obj)
        return items

    all_values = flatten(cleaned_data)
    value_counts = Counter(all_values)

    return {"data": cleaned_data, "value_counts": value_counts}

