    for key in key_path:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            raise KeyError(f"Key '{key}' not found in JSON structure")

    def extract_numeric_values(obj):
        values = []
        if isinstance(obj, dict):
            for v in obj.values():
                values.extend(extract_numeric_values(v))
        elif isinstance(obj, list):
            for item in obj:
                values.extend(extract_numeric_values(item))
        elif isinstance(obj, (int, float)):
            values.append(obj)
        return values

    numeric_values = extract_numeric_values(current)
    if not numeric_values:
        raise ValueError("No numeric data found")

    fig, ax = plt.subplots()
    sns.boxplot(data=numeric_values, ax=ax)
    ax.set_title(f'Boxplot of data at path {key_path}')
    return fig

