import pandas as pd
import json
import os
import math

def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("JSON data is malformed")
    if not isinstance(data, list) or len(data) == 0:
        raise ValueError("JSON data is empty or not a list")
    validated = []
    for item in data:
        if not isinstance(item.get("country"), str):
            raise ValueError("Non-string country name")
        pop = item.get("population")
        if not isinstance(pop, (int, float)) or isinstance(pop, bool):
            raise ValueError("Non-numeric population")
        if pop < 0:
            raise ValueError("Negative population")
        if isinstance(pop, float):
            pop = math.floor(pop)
        validated.append({"Country": item["country"], "Population": pop})
    df = pd.DataFrame(validated)
    file_path = os.path.join(output_dir, file_name)
    try:
        df.to_csv(file_path, index=False)
    except (IOError, OSError):
        raise IOError("Cannot write file to specified directory")
    return file_path, df
